from pathlib import Path
import json
from scripts import check_site_asset_refs as refs
missing=refs.find_dangling(Path('site').resolve())
owned={target:['china.html'] for target,pages in missing.items() if 'china.html' in pages}
hard={t:p for t,p in owned.items() if not refs._TICKER_PAGE_RE.match(t)}
soft={t:p for t,p in owned.items() if refs._TICKER_PAGE_RE.match(t)}
print(json.dumps({'scope':'china.html via existing find_dangling parser/resolver','hard':hard,'soft_ticker_warnings':soft},sort_keys=True))
raise SystemExit(1 if hard else 0)
